package com.seanpereyra.mvk.data

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import com.seanpereyra.mvk.R
import java.util.Collections
import kotlin.random.Random

/**
 * Randomizer sound effects. Uses SoundPool (Android's low-latency player for short game sounds)
 * on the game/media channel, so the sounds follow your media volume and still play when the
 * phone is on vibrate. All calls do nothing when SFX are turned off in Settings.
 *
 * The sounds are res/raw/sfx_*.wav, generated by tools/make_sfx.py.
 */
class Sfx(context: Context) {
    @Volatile var enabled: Boolean = true

    private val pool = SoundPool.Builder()
        .setMaxStreams(6)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    private val loaded: MutableSet<Int> = Collections.synchronizedSet(mutableSetOf())
    private val spinId: Int
    private val tickId: Int
    private val winId: Int

    init {
        pool.setOnLoadCompleteListener { _, id, status -> if (status == 0) loaded += id }
        spinId = pool.load(context, R.raw.sfx_spin, 1)
        tickId = pool.load(context, R.raw.sfx_tick, 1)
        winId = pool.load(context, R.raw.sfx_win, 1)
    }

    /** Clack for each shuffling frame, with a slightly different pitch every time. */
    fun blip() = play(spinId, volume = 0.6f, rate = 0.9f + Random.nextFloat() * 0.35f)

    /** Tick when a character locks in place. */
    fun tick() = play(tickId, volume = 0.85f)

    /** Chime when the final code lands. */
    fun win() = play(winId, volume = 0.9f)

    private fun play(id: Int, volume: Float, rate: Float = 1f) {
        if (!enabled || id !in loaded) return
        pool.play(id, volume, volume, 1, 0, rate)
    }

    fun release() = pool.release()
}
